import fs from "fs";
import path from "path";
import { runBugReportPostprocess } from "./bugReport/privacyArtifacts";

const AUDIT_PARTITION_KEY_PATTERN = /^\s{6}audit_\d{8}:\s\{$/;

function getBraceDelta(line: string) {
  const openBraces = (line.match(/\{/g) ?? []).length;
  const closeBraces = (line.match(/\}/g) ?? []).length;
  return openBraces - closeBraces;
}

function stripAuditPartitions(content: string) {
  const lines = content.split("\n");
  const filtered: string[] = [];

  let skippingPartitionBlock = false;
  let braceDepth = 0;

  for (const line of lines) {
    if (!skippingPartitionBlock && AUDIT_PARTITION_KEY_PATTERN.test(line)) {
      skippingPartitionBlock = true;
      braceDepth = getBraceDelta(line);
      continue;
    }

    if (skippingPartitionBlock) {
      braceDepth += getBraceDelta(line);
      if (braceDepth <= 0) {
        skippingPartitionBlock = false;
      }
      continue;
    }

    filtered.push(line);
  }

  return filtered.join("\n");
}

async function run() {
  const targets = process.argv.slice(2);
  if (targets.length === 0) {
    throw new Error("Usage: npx tsx scripts/PostprocessSupabaseTypes.ts <file-path> [more-file-paths...]");
  }

  for (const target of targets) {
    const resolvedPath = path.resolve(target);
    const original = fs.readFileSync(resolvedPath, "utf8");
    const updated = stripAuditPartitions(original);
    if (updated !== original) {
      fs.writeFileSync(resolvedPath, updated, "utf8");
      // eslint-disable-next-line no-console
      console.log(`Removed rotating audit partition types from ${target}`);
    } else {
      // eslint-disable-next-line no-console
      console.log(`No rotating audit partition types found in ${target}`);
    }

    // The bug reporter's privacy classification must cover the public schema (lib/bugReport/privacy.ts).
    if (path.basename(resolvedPath) === "SupabaseTypes.d.ts") {
      const error = await runBugReportPostprocess(updated);
      if (error) {
        // eslint-disable-next-line no-console
        console.error(error);
        process.exitCode = 1;
      }
    }
  }
}

run().catch((e) => {
  // eslint-disable-next-line no-console
  console.error(e);
  process.exit(1);
});
import { FlatCompat } from "@eslint/eslintrc";

const compat = new FlatCompat({ baseDirectory: import.meta.dirname });

// Bans hard-coded light-palette backgrounds paired with white foregrounds — the exact
// pattern that produced the WCAG 1.4.3 violations surfaced by the a11y audit on PR #732.
// Use `colorPalette="<hue>" variant="solid"` instead so theme tokens (bumped to .700
// for AA contrast) drive the pairing centrally.
const PALETTE_SHADE_RE = "^(green|red|blue|orange|yellow|teal|pink|purple)\\.[3-6]00$";
const FORBIDDEN_PALETTE_BG_WITH_WHITE =
  "JSXOpeningElement:has(JSXAttribute[name.name='bg'][value.value=/" +
  PALETTE_SHADE_RE +
  "/]):has(JSXAttribute[name.name='color'][value.value='white'])";

const eslintConfig = [
  // design-sync inputs are tooling artifacts (esbuild-compiled, never imported by
  // the app, regenerated each sync, intentionally full of `any`/mock shims).
  { ignores: [".design-sync/**"] },
  ...compat.config({ extends: ["next/core-web-vitals", "next/typescript", "prettier"] }),
  {
    linterOptions: { reportUnusedDisableDirectives: "warn" },
    rules: {
      "no-console": "warn",
      "no-restricted-syntax": [
        "error",
        {
          selector: FORBIDDEN_PALETTE_BG_WITH_WHITE,
          message:
            'Don\'t pair a raw `bg="<palette>.500|600|…"` with `color="white"` — it bypasses the theme and typically fails WCAG 1.4.3 (e.g. green.600 + white = 3.29:1). Use `colorPalette="<hue>" variant="solid"` so the AA-bumped solid/contrast tokens apply.'
        }
      ]
    }
  }
];

export default eslintConfig;
/**
 * Types for the privacy classification in `privacy.ts` (spec §4.3), kept apart so the generator and
 * the postprocess script can import them without loading the whole classification.
 */

export type PiiKind = "name" | "email" | "handle" | "grade" | "free_text" | "none";

export const PII_KINDS: readonly PiiKind[] = ["name", "email", "handle", "grade", "free_text", "none"];

/**
 * Marks a value as one row (an object) or several rows (an array of objects) of a public table or
 * view; its keys are classified through that relation's `COLUMNS` entries. Used for SETOF RPCs and
 * for Json results that embed whole rows (e.g. `to_jsonb(p.*)`).
 */
export type TableRef = { readonly $table: string };

/**
 * JSONPath (subset: `$`, `.key`, `[*]`) to kind. The most specific path that covers a value decides
 * its kind, and a path to an object or array covers everything beneath it. `none` must be explicit:
 * a value no path covers is reported as unclassified, never treated as `none`.
 */
export type JsonPathMap = Readonly<Record<string, PiiKind | TableRef>>;

/**
 * An RPC's result: a kind for scalar returns and arrays of scalars, a `TableRef` for rows of a
 * table (SETOF or a single row), or a JSONPath map for Json and `RETURNS TABLE(...)` results.
 */
export type RpcClassification = PiiKind | TableRef | JsonPathMap;

export function isTableRef(v: unknown): v is TableRef {
  return typeof v === "object" && v !== null && typeof (v as { $table?: unknown }).$table === "string";
}

export function isPiiKind(v: unknown): v is PiiKind {
  return typeof v === "string" && (PII_KINDS as readonly string[]).includes(v);
}

/** One path segment: an object key, or `*` for every array element. */
export type JsonPathSegment = { key: string } | { any: true };

const SEGMENT = /\.([^.[\]]+)|\[\*\]/y;

/** Parses the JSONPath subset. Throws on anything outside `$`, `.key`, `[*]`. */
export function parseJsonPath(path: string): JsonPathSegment[] {
  if (!path.startsWith("$")) throw new Error(`JSONPath must start with $: ${path}`);
  const segments: JsonPathSegment[] = [];
  SEGMENT.lastIndex = 1;
  while (SEGMENT.lastIndex < path.length) {
    const start = SEGMENT.lastIndex;
    const m = SEGMENT.exec(path);
    if (!m) throw new Error(`unsupported JSONPath syntax at offset ${start}: ${path}`);
    segments.push(m[1] !== undefined ? { key: m[1] } : { any: true });
  }
  return segments;
}

/** Canonical text of a concrete path, with array indexes written as `[*]`, for lookups in a JsonPathMap. */
export function formatJsonPath(segments: readonly JsonPathSegment[]): string {
  return "$" + segments.map((s) => ("key" in s ? `.${s.key}` : "[*]")).join("");
}

/** Shape of `generated/relationships.json`: each public table and view, with its foreign keys. */
export type RelationshipsJson = Record<
  string,
  { kind: "table" | "view"; fks: { name: string; columns: string[]; ref: string }[] }
>;

/** Shape of `generated/edgeFunctionWrappers.json`: edge function slug to the wrappers that invoke it. */
export type EdgeWrappersJson = Record<string, string[]>;
/**
 * Privacy classification for the bug reporter's taint set (spec §4.3).
 *
 * DRAFT PENDING HUMAN APPROVAL (HU6). Generated by `scripts/bugReport/generatePrivacyDraft.ts` from
 * column-name heuristics, `docs/operations/data-retention.md` §"PII / grades", the SQL of each RPC,
 * and the response types of `lib/edgeFunctions.ts`. Entries marked `// UNCERTAIN` are guesses the
 * reviewer should check; `lib/bugReport/PRIVACY_REVIEW.md` explains the rules and what to look at.
 *
 * Edit entries here by hand. Rerun the generator after a schema change (`npm run client-local` fails
 * and names the missing keys); it keeps existing entries and adds `// DRAFT` entries for new keys.
 *
 * - COLUMNS: every column of every table and view in the public schema, key "table.column".
 * - RPCS: a kind for scalar returns (and arrays of scalars), `{ $table }` for table rows, or a
 *   JSONPath map for Json and `RETURNS TABLE` results.
 * - EDGE_FUNCTIONS: every exported wrapper in lib/edgeFunctions.ts, JSONPath map of its response.
 *   Wrappers that only call RPCs map `$` to "none" here; the RPCS entries classify their results.
 *
 * JSONPath subset: `$`, `.key`, `[*]`. There is no default kind: `none` is always explicit.
 */
import type { JsonPathMap, PiiKind, RpcClassification } from "./privacyTypes";

export type { JsonPathMap, PiiKind, RpcClassification, TableRef } from "./privacyTypes";

